[ExtensionOf(classStr(WHSInstrumentationLogger))]
internal final class WHSWorkExecuteDisplayFrameworkActivitiesInstrumentationLogger_Extension
{
    private WHSWorkExecuteDisplayFrameworkActivities activities;

}

Method.Source:
    internal WHSWorkExecuteDisplayFrameworkActivities workExecuteDisplayFrameworkActivities()
    {
        if (!activities)
        {
            activities = WHSWorkExecuteDisplayFrameworkActivities::newFromLogger(this);
        }

        return activities;
    }
